def cols_in_atlas(atlas_name: str) -> int:
    """atlas 内每行多少帧 (= total / 4 个方向)."""
    n = len(FM_FRAMES.get(atlas_name.lower(), []))
    return n // 4 if n else 0

def get_frame(atlas_name: str, list_idx: int):
    """返回 (x, y, w, h, ax, ay) 或 None."""
    arr = FM_FRAMES.get(atlas_name.lower())
    if not arr or list_idx < 0 or list_idx >= len(arr):
        return None
    return arr[list_idx]